insert into public.ce_course3_resources(id,data) values
('course3_module5_pdf','{"base64": "", "sha256": "a9d205920a036981e68f866d8e4fcffe6b0049ea19673b63b618d44f570b7c82", "filename": "CE_HALO_Course3_Module05_Medication_Errors_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course3_module5_questions','[{"module_id": "course_3_module_5", "question_id": "course_3_module_5_q01", "question_number": 1, "stem": "Per NCC MERP and ISMP, a medication error is best defined as:", "choice_a": "Any preventable event that may cause or lead to inappropriate medication use or patient harm while the medication is in the control of a healthcare professional, patient, or consumer", "choice_b": "Any patient-reported side effect after emergence", "choice_c": "Any deviation from a written medication order that is discovered after the case", "choice_d": "Any adverse drug reaction that occurs during anesthesia care", "correct_choice": "a", "rationale": "NCC MERP defines a medication error as any preventable event that may cause or lead to inappropriate medication use or patient harm while the medication is in the control of a healthcare professional, patient, or consumer. This encompasses both errors that reach the patient and those intercepted (near misses).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q02", "question_number": 2, "stem": "A CRNA intends to draw up ondansetron but grabs phenylephrine because the two syringes are similarly positioned on the anesthesia machine. Which classification best applies?", "choice_a": "Adverse drug event unrelated to error", "choice_b": "Slip — failure of execution despite the correct plan", "choice_c": "Reckless behavior under just-culture principles", "choice_d": "Mistake — failure of planning or knowledge", "correct_choice": "b", "rationale": "A slip is a failure of execution despite the correct plan, typically caused by habit capture, distraction, or workspace design. A mistake is a failure of planning or knowledge (the plan itself is wrong). Slips are best addressed with system engineering.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q03", "question_number": 3, "stem": "Which of the following is a latent error rather than an active error?", "choice_a": "The CRNA injects rocuronium instead of cefazolin", "choice_b": "The CRNA administers medication to the wrong patient", "choice_c": "Look-alike vial caps are stored together on the anesthesia cart without a barcode reader", "choice_d": "The CRNA programs an infusion rate at 10 times the intended value", "correct_choice": "c", "rationale": "Latent errors are hidden system weaknesses (look-alike storage, missing barcode technology, understaffing) that make active errors more likely. The remaining choices are active errors at the point of care.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q04", "question_number": 4, "stem": "Which of the following medications is not on the 2024 ISMP List of High-Alert Medications in Acute Care Settings?", "choice_a": "IV opioids and epidural opioids", "choice_b": "Concentrated potassium chloride", "choice_c": "Neuromuscular blocking agents", "choice_d": "Acetaminophen 650 mg oral", "correct_choice": "d", "rationale": "The 2024 ISMP High-Alert list includes NMBAs, IV and epidural opioids, concentrated electrolytes, insulin, anticoagulants, sedatives/hypnotics for procedural use, and local anesthetics ≥0.5% or given epidurally. Standard oral acetaminophen is not on the list.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q05", "question_number": 5, "stem": "Which look-alike/sound-alike pattern was the focus of a 2024 APSF Newsletter multistakeholder alert about a recurrent wrong-drug, wrong-route error in anesthesia?", "choice_a": "Tranexamic acid mistaken for bupivacaine or ropivacaine during neuraxial anesthesia", "choice_b": "Ephedrine mistaken for epinephrine", "choice_c": "Heparin 10 units/mL mistaken for heparin 10,000 units/mL", "choice_d": "Vecuronium mistaken for Versed", "correct_choice": "a", "rationale": "The June 2024 APSF Newsletter published a multistakeholder analysis of recurrent inadvertent neuraxial injection of tranexamic acid (TXA) in place of bupivacaine or ropivacaine, an event with mortality of 40–50% in published series.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q06", "question_number": 6, "stem": "Which APSF acronym best summarizes the four pillars of perioperative medication safety reaffirmed at the 2024 Stoelting Consensus Conference?", "choice_a": "SAFE — Screening, Awareness, Feedback, Education", "choice_b": "STPC — Standardization, Technology, Pharmacy/prefilled, Culture", "choice_c": "MEDS — Monitor, Evaluate, Document, Standardize", "choice_d": "CHECK — Confirm, Handoff, Educate, Coordinate, Know", "correct_choice": "b", "rationale": "APSF frames medication safety around Standardization (concentrations, labels), Technology (BCMA, smart pumps, EHR), Pharmacy/prefilled syringes for high-risk drugs, and Culture (reporting, teamwork, disclosure).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q07", "question_number": 7, "stem": "Per current ASRA guidance, the first dose of 20% lipid emulsion for adult LAST is:", "choice_a": "5 mL/kg bolus, followed by 1 mL/kg/min infusion", "choice_b": "3 mL/kg bolus, no infusion", "choice_c": "1.5 mL/kg bolus, followed by 0.25 mL/kg/min infusion", "choice_d": "10 mL/kg bolus over 10 minutes", "correct_choice": "c", "rationale": "ASRA''s 2020 (reaffirmed 2024) LAST checklist recommends 20% lipid emulsion 1.5 mL/kg IV bolus over 2–3 minutes followed by 0.25 mL/kg/min infusion, with bolus and infusion adjustments per patient response.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q08", "question_number": 8, "stem": "Which epinephrine dose does ASRA recommend for hemodynamic support during LAST in adults?", "choice_a": "Vasopressin 40 units IV push", "choice_b": "No epinephrine — only lipid emulsion", "choice_c": "Standard ACLS doses of 1 mg IV every 3–5 minutes", "choice_d": "Reduced doses of 10–100 mcg IV boluses", "correct_choice": "d", "rationale": "ASRA recommends smaller, incremental epinephrine boluses (10–100 mcg in adults) during LAST because standard ACLS doses can worsen arrhythmias and impair lipid rescue. Vasopressin is specifically to be avoided.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q09", "question_number": 9, "stem": "Which of the following is required by Joint Commission National Patient Safety Goal 03.04.01?", "choice_a": "Labeling all medications, medication containers, and other solutions on and off the sterile field in perioperative and other procedural settings", "choice_b": "Elimination of manual medication preparation in all facilities", "choice_c": "Barcode scanning of every medication in every OR", "choice_d": "Independent double checks of every anesthesia medication", "correct_choice": "a", "rationale": "NPSG 03.04.01 requires labeling of all medications, medication containers, and other solutions on and off the sterile field in perioperative and procedural settings — a standard designed specifically to prevent wrong-drug and wrong-route events.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q10", "question_number": 10, "stem": "Which four elements must a plaintiff establish in a CRNA medication-error negligence claim?", "choice_a": "Intent, breach, causation, damages", "choice_b": "Duty, breach, causation, damages", "choice_c": "Duty, foreseeability, mitigation, damages", "choice_d": "Duty, malice, causation, punitive damages", "correct_choice": "b", "rationale": "Every U.S. jurisdiction requires the classical four elements of negligence: duty, breach of the standard of care, causation (actual and proximate), and compensable damages.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q11", "question_number": 11, "stem": "Under Just Culture principles, which category of behavior warrants consoling the individual and redesigning the system rather than disciplinary action?", "choice_a": "Reckless behavior", "choice_b": "At-risk behavior", "choice_c": "Human error (inadvertent slip, lapse, or mistake)", "choice_d": "Willful misconduct", "correct_choice": "c", "rationale": "Marx''s Just Culture model calls for consoling the individual and repairing the system after human error; coaching for at-risk behavior; and remedial or disciplinary action only for reckless behavior (conscious disregard of substantial, unjustifiable risk).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q12", "question_number": 12, "stem": "The 2022 criminal conviction of nurse RaDonda Vaught involved inadvertent administration of which medication in place of the intended Versed (midazolam)?", "choice_a": "Vasopressin", "choice_b": "Vancomycin", "choice_c": "Verapamil", "choice_d": "Vecuronium", "correct_choice": "d", "rationale": "Ms. Vaught inadvertently administered vecuronium (a neuromuscular blocker) instead of Versed (midazolam) after overriding the automated dispensing cabinet safety features. Nursing and safety organizations widely warned that the criminal prosecution would suppress voluntary reporting.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q13", "question_number": 13, "stem": "A CRNA discovers that the propofol infusion line was not connected to the patient''s IV during a paralyzed general anesthetic. The patient reports intraoperative awareness with recall. Which combination of preventive measures is most directly indicated?", "choice_a": "Verify the infusion line to the patient before induction and monitor end-tidal anesthetic concentration or processed EEG when infusion-only techniques are used", "choice_b": "Perform routine intraoperative naloxone administration", "choice_c": "Reduce opioid dose in future cases", "choice_d": "Discontinue the use of propofol infusions", "correct_choice": "a", "rationale": "Line-to-patient verification and continuous monitoring of anesthetic depth (end-tidal anesthetic gas or processed EEG) are the recognized safeguards against unrecognized delivery failures during infusion-based general anesthesia — the classic setup for awareness in a paralyzed patient.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q14", "question_number": 14, "stem": "Which monitoring parameter, per current AANA and ASA standards, is required for all patients receiving moderate or deep sedation, including MAC?", "choice_a": "Invasive arterial blood pressure", "choice_b": "Continuous end-tidal CO2 (capnography)", "choice_c": "Transcutaneous oxygen tension", "choice_d": "Bispectral index (BIS)", "correct_choice": "b", "rationale": "Current AANA and ASA standards require continuous capnography for all moderate/deep sedation and general anesthesia to detect hypoventilation, obstruction, and apnea earlier than pulse oximetry alone.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q15", "question_number": 15, "stem": "During a wrong-drug injection into a neuraxial catheter, which of the following is the most important immediate step to prevent recurrence in the future?", "choice_a": "Require an anesthesiologist to inject all neuraxial medications", "choice_b": "File a lawsuit against the vial manufacturer", "choice_c": "Never inject a medication into a neuraxial catheter that the CRNA has not personally verified by label and, when available, by barcode scan", "choice_d": "Discontinue the use of neuraxial anesthesia", "correct_choice": "c", "rationale": "Personal label verification (and barcode scan when available) immediately before neuraxial injection is the single most effective safeguard against catastrophic wrong-drug or wrong-route events, per APSF and ISMP.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q16", "question_number": 16, "stem": "Which of the following is the most appropriate documentation practice immediately after a medication error?", "choice_a": "Chart that an incident report was filed and describe the suspected root cause", "choice_b": "Amend prior chart entries to reflect the corrected clinical picture", "choice_c": "Delay documentation until legal counsel reviews the chart", "choice_d": "Document a timely, objective, factual account of the medication, assessment, interventions, notifications, and patient response — and file the incident report separately", "correct_choice": "d", "rationale": "Documentation should be timely, objective, and factual. Incident reports are separate from the medical record and generally should not be referenced in the chart. Prior entries must never be altered or backdated; late entries must be labeled as such.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q17", "question_number": 17, "stem": "Which external reporting system is most appropriate for a CRNA who identifies a defect in vial labeling that contributed to a wrong-drug event?", "choice_a": "FDA MedWatch", "choice_b": "Facility marketing department", "choice_c": "AANA membership hotline", "choice_d": "State department of transportation", "correct_choice": "a", "rationale": "FDA MedWatch is the appropriate voluntary reporting channel for serious adverse events and product-quality problems (including labeling and packaging defects). ISMP MERP is a complementary, ISMP-operated program.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q18", "question_number": 18, "stem": "Which of the following is the correct order of confirmation steps at the anesthesia workstation immediately before administering a medication?", "choice_a": "Confirm the medication only with the circulating nurse after administration", "choice_b": "Read the label when the vial is retrieved, again when the medication is drawn up, and again immediately before administration — with barcode scan when available", "choice_c": "Draw up, label, administer, then read the label", "choice_d": "Rely on vial-cap color, then administer", "correct_choice": "b", "rationale": "Reading the label three times (retrieval, draw-up, administration) plus barcode scan when available is the standard risk-reduction bundle recommended by APSF, ISMP, and AANA.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q19", "question_number": 19, "stem": "Which quantitative train-of-four ratio is the current recommended threshold for tracheal extubation to minimize residual neuromuscular blockade?", "choice_a": "≥ 1.2", "choice_b": "≥ 0.7", "choice_c": "≥ 0.9", "choice_d": "≥ 0.5", "correct_choice": "c", "rationale": "Current APSF, ASA, and AANA guidance recommends quantitative TOF monitoring with a ratio ≥ 0.9 before extubation to minimize residual neuromuscular blockade and postoperative respiratory complications.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q20", "question_number": 20, "stem": "Which of the following medications is not reversed by sugammadex?", "choice_a": "Rocuronium", "choice_b": "Vecuronium", "choice_c": "None — sugammadex reverses all three aminosteroid NMBAs", "choice_d": "Cisatracurium", "correct_choice": "d", "rationale": "Sugammadex encapsulates aminosteroid NMBAs (rocuronium, vecuronium, and to a lesser extent pancuronium) but does not reverse benzylisoquinolinium agents such as cisatracurium. Reversal choice must match the NMBA class and the current depth of block.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q21", "question_number": 21, "stem": "A structured handoff between the CRNA and the PACU nurse should include, at minimum:", "choice_a": "Medications given, infusions currently running, allergies, patient response, and anticipated next doses", "choice_b": "The CRNA''s personal opinion of the case", "choice_c": "The surgeon''s preferences only", "choice_d": "The billing code for anesthesia services", "correct_choice": "a", "rationale": "ISMP Canada''s 2024 PACU multi-incident analysis and the AANA Standards emphasize structured handoffs that include medications given, infusions running, allergies, patient response, and anticipated next doses. I-PASS or SBAR formats are recommended.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q22", "question_number": 22, "stem": "Vicarious liability in a CRNA medication-error case may extend to which of the following parties?", "choice_a": "The medication manufacturer under products-liability theories when packaging design contributed to the error", "choice_b": "All of the above, depending on facts and employment structure", "choice_c": "The facility and the anesthesia group", "choice_d": "A medically directing anesthesiologist under TEFRA rules", "correct_choice": "b", "rationale": "Vicarious liability may reach the facility, group, medically directing anesthesiologist, and (occasionally) manufacturer, depending on employment status, medical-direction structure, credentialing, and packaging design contributions.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q23", "question_number": 23, "stem": "Which of the following statements about the Patient Safety and Quality Improvement Act of 2005 (PSQIA) is most accurate?", "choice_a": "It eliminates civil liability for medication errors", "choice_b": "It requires public reporting of every medication error", "choice_c": "It provides federal confidentiality and privilege protection for patient-safety work product submitted through a certified Patient Safety Organization (PSO)", "choice_d": "It preempts all state peer-review protection statutes", "correct_choice": "c", "rationale": "PSQIA (42 U.S.C. §§299b-21–299b-26) creates federal confidentiality and privilege for patient-safety work product submitted through certified PSOs. State peer-review protections continue to apply and are not preempted.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q24", "question_number": 24, "stem": "Which of the following best captures the AANA and APSF position on nonpunitive medication-error reporting?", "choice_a": "Reporting is optional and generally discouraged for individual practitioners", "choice_b": "Reporting should be limited to events resulting in patient death", "choice_c": "Only pharmacy staff should report medication errors", "choice_d": "Voluntary reporting of near misses and actual errors is essential for system learning; punitive responses to human error suppress reporting and worsen patient safety", "correct_choice": "d", "rationale": "AANA, APSF, ISMP, and Joint Commission consistently endorse voluntary, nonpunitive reporting of near misses and errors as the foundation of medication-safety improvement. Punitive responses to human error suppress reporting and are associated with worse safety outcomes.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_5", "question_id": "course_3_module_5_q25", "question_number": 25, "stem": "A CRNA in an outpatient endoscopy suite plans MAC with propofol and fentanyl for a high-risk patient with obesity, OSA, and renal dysfunction. Which of the following most reduces medication-related liability exposure?", "choice_a": "Verify the medically directing anesthesiologist''s supervisory presence per policy, use continuous capnography, ensure immediate availability of naloxone and airway rescue equipment, and document the plan and monitoring", "choice_b": "Reserve intubation for cardiac arrest", "choice_c": "Skip continuous capnography to reduce alarms", "choice_d": "Rely on pulse oximetry alone because MAC does not require capnography", "correct_choice": "a", "rationale": "High-risk MAC patients require full standard monitoring (including capnography), clear supervisory presence per medical-direction rules, immediate rescue readiness (naloxone, airway equipment), and complete documentation — the safeguards most often missing in published sedation-related closed-claim cases.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course3_resources where id='course3_module5_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course3_catalog where id='1047243'),'Course must remain staged';
end $$;
commit;